contract InvMutTest {
    C c;
    constructor() { c = new C(address(this), 0); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(amount > 0);
        require(address(this).balance >= amount);

        // Send Ether to c so a successful OpenToThePublic (as well as any later calls) has some balance to work with.
        // This is done via a call that changes c's state: the fallback is payable and does not revert.
        // The test contract is the deployer/owner of c, so it can open the contract.
        c.OpenToThePublic(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.OpenToThePublic(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        // General rule: for the owner (the test contract), OpenToThePublic must not revert,
        // and the observable effect is that the contract is open to the public so that
        // subsequent wagering is allowed. A non-owner call would revert. Since the test
        // contract is always the owner, the rule here is that the owner's call succeeds.
        assert(!reverted);
    }

    receive() external payable {}
}

